    "room.480.chat.0.text": "You need to speak with the Lady of the Cave, {guide}. ",
    "room.480.chat.1.text": "Greeting and welcome to sanctuary. I am the Lady of the Cave, {guide}. You may wonder why you're here and if you're safe. Have no fears new one, this is a place of security and acceptance. We were all like you at one time. ",
    "room.480.chat.2.text": "Yes. We were all victims of the cult. Smuggled, or nearly so, taken from our homes across the land to birth that disastrous Azrael against our wishes. The {queen} came to our rescue and freed us from the Cult of C.U.M. so that we may continue to live. ",
    "room.480.chat.13.text": "One day I met with a new mistress. It was stupid, I should have been more safe, but she looked amazing! I agreed to get tied up with a hood over my head with her and she ended up kidnapping me. She must have drugged me somehow because everything was black then I woke up at the cult place in a cell. That {ubel} guy beat me once a week and they took turns on me so many times. ",
    "room.480.chat.14.text": "After about six months I was taken to the cum bath ritual and changed into the girl you see now. I was about to be inseminated with the seed of Azrael, but the {queen} snuck into my cell and freed me and brought me here. I'm so happy she freed me. I'm sure they would have killed me if I stayed. I'm forever in her debt. That's why I stay to help others like me. ",
    "room.480.chat.16.text": "At first I was scared, but I've grown to love my pussy. I even changed my name from John to {vag} after I accepted this is who I am now. ",
    "room.480.chat.21.text": "All new arrivals must first speak with {guide}. ",
    "room.479.chat.8.text": "When they found her with her aborted fetus they tied her to a tree in the swamps to die of exposure or dehydration while the mosquitoes fed on her. Luckily the {queen} found her and saved her from death. Unable to talk and tired from the years of abuse she was on the edge of ending her own life. That's when I found her brought her some soup. ",
    "room.479.chat.50.text": "Well well well. {ledja}, you brought someone to replace you. This replacement will do nicely. Per our agreement you're free to go. Remember, one word to anyone and you'll be back in the dungeons of the cult. Now scat! ",
    "room.479.chat.52.text": "I'm {ff} and my friends and I now own your ass. You see, for quite some time we've known about this little hole filled with run away sissies. The only reason you all are still here is because they haven't told {ubel} about this place. If he knew the entire cult would come down on you and all your sissy friends. And it would be bad. Really bad. ",
    "room.479.chat.66.text": "You did good for your first day. We took it easy on you. Really easy. I'll be back tomorrow night with more friends. Be sure to be here. You know the last girl, {ledja}, served our cocks for over a year before she gave you up. How many years are you going to be our little cock slave? ",
    "room.479.chat.72.text": "{jenna} told me everything on the way down here. This is most troubling. You really can't stay here. I don't trust them not to try something drastic that you won't be able to handle. {me} follow me back upstairs. {jenna} you'll have to take {playerPronoun} place. Stay strong, you'll only be stuck here until we can take care of this problem. Just remember to lube up before they come, an unlubed hole can be quite painful. ",
    "room.479.chat.72.choice.0": "[Follow the {queen} upstairs]",
    "room.478.chat.9.text": "All five kidnappers took turns raping us over the 10 hour drive to their compound. Poor Nala was a virgin before we were kidnapped. Some creep named {river} was really brutal with her. If I ever see him I'm going to cut his wiener right the fuck off! ",
    "room.478.chat.9.choice.0": "I know {river}! He's such an asshole! I hate him too! ",
    "room.478.chat.12.text": "She was the first to take the CUM bath ritual. As you can see the transformation worked, but during the impregnation ritual the evil spirits decided she wasn't worthy and ripped her eyes out. She didn't even want to do it, they made her! And that evil fucking spirit ripped out her eyes anyway. Fucking horrible. Then they threw her in the swamps to die. Luckily the {queen} was able to find her and save us from fucking dying. ",
    "room.478.chat.19.text": "Ugh! {guide} always sends the clueless new girls around like they're on some kinda mission to save themselves. Like you, we all had terrible stories of our time with the cult, but they are better than the stories of those that did not survive their time there. Only a few girls have chosen to leave and those girls are gone. Disappeared. Vanished. Poof. ",
