    "room.477.chat.9.text": "I told you to lay down before you fell down. Why does no one ever listen to me. {me}, I had a feeling I may be seeing you. You're more famous than you know. ",
    "room.477.chat.10.text": "I won't bore you with a retelling of your life's story. But I do know that you work for {missy}. The girl that was taken by Ubel. That ordeal was really quite something. They may not have taken you back yet, but they will, in time. In a way I'm glad you've found your way here. ",
