    "room.408.chat.47.text": "Hi {stormy}, anything new?",
    "room.408.chat.48.text": "Anything new? Why don't you...",
    "room.408.chat.49.text": "Is that {me}!!! I'm so glad you're here! Oh wow! Sorry about running off on you. I was just shocked. I've been thinking about you every day since. You're so beautiful and wonderful. Did I say how glad I am that I found you?",
