    "room.408.chat.51.text": "Haha. I'm not going to date my step sister. Gross. {stormy}'s just letting me crash here for a bit. I totally lost my job and ended up losing my apartment trying to get even with that asshole, Mr. Rex! I'll make him pay for what he did to My sister, Reya!",
    "room.408.chat.51.choice.0": "What did he do to Reya?",
    "room.408.chat.52.text": "She was working late and he and his friend cornered her and tried to rape her. Ripped her panties right off. They touched her all over, but she was able to escape before they could do anything too bad. She went to the police, but those assholes lied and said she was asking for it.",
    "room.408.chat.52.choice.0": "That's terrible!",
    "room.408.chat.53.text": "I know. My boss at the plant caught me plotting my revenge and fired me on the spot. Said I was crazy. It's not crazy to want to get back at the man that tried to rape my sister! So glad she got away or I would be plotting something more evil!",
    "room.408.chat.54.text": "Calm down, Norman Bates, you'll scare her away. I'm going to get some coffee and let you two catch up. Bye bye.",
    "room.408.chat.54.choice.0": "oh",
    "room.408.chat.55.text": "Now that she's gone there's something I've been playing over and over in my head.",
    "room.408.chat.55.choice.0": "Yes?",
    "room.408.chat.56.text": "He's kissing me? He's kissing me! A bit of a surprise, but his lips are so soft. He is a good kisser.",
    "room.408.chat.56.choice.0": "*uncontrolled moan*",
    "room.408.chat.57.text": "Sorry. That was a bit forward. I just wanted to let you know what I thought. I know this is only our second date, but I think I love you. When I saw your face I knew you were the girl for me.",
    "room.408.chat.57.choice.0": "I've been thinking a lot about you and our first date too.",
    "room.408.chat.58.text": "If {elijah} is here I need to look more feminine or he'll know something's up. Let me go change before I go in looking for him.",
    "room.408.chat.59.text": "That makes me so happy! You deserve a proper date. Come by here tomorrow and I'll take you out. I can't wait to see you again!",
    "room.408.chat.59.choice.0": "I can't wait to see you either. I'll see you here tomorrow.",
    "room.408.chat.60.text": "Well, I know he's here, and I know he'll be here for a while. I do feel guilty about turning him in. Even more so that he seems so in love with me. I just don't know if I should tell {missy} or not that he's here.",
    "room.408.chat.61.text": "So glad you came! Let me take you out to my favorite restaurant!",
    "room.408.chat.61.choice.0": "ok!",
    "room.408.chat.62.text": "Hello. Your finest table for my girlfriend and I please.",
    "room.408.chat.63.text": "Our finest table? Haha, sure. Right this way sir.",
    "room.408.chat.64.text": "I'm so glad you decided to go out with me again. My heart is fluttering. I got you some roses. They're almost as pretty as you. I made sure to get red since red roses are the color of love. They guy who sold them to me told me. A girl as amazing as you should have a room full of roses so you know how much you're loved everyday.",
    "room.408.chat.64.choice.0": "Awww. Thank you. They are lovely.",
    "room.408.chat.65.text": "*hrumph* If it isn't the little bitch. You, boy, you know this girl is a massive bitch and no one likes her. I even heard she's slept with every man in this town. Her butt is probably full of cum right now! tbbbth",
    "room.408.chat.65.choice.0": "Please just get our food.",
    "room.408.chat.66.text": "Wow. What a bitch! She's probably just jealous of your beauty. You don't have to defend yourself to her. I know a girl like you doesn't sleep around. You're way too pretty for that. Fuck her. Let's eat. It'll just piss her off more hehe.",
    "room.408.chat.66.choice.0": "Yeah Let's eat",
    "room.408.chat.67.text": "Hi {me}, who's the lucky boy?",
    "room.408.chat.67.choice.0": "It's my boyfriend {elijah}.",
    "room.408.chat.68.text": "{elijah}, you're on a date with the most wonderful girl we've ever met. You sure are a lucky boy, just treat her right ok. I'll go get your food.",
    "room.408.chat.68.choice.0": "Oh you. Thanks so much.",
    "room.408.chat.69.text": "You know. I come here way too much. It's just those girls are so hot. Not as hot as you, but there's something special about them. And they're really so friendly.",
    "room.408.chat.69.choice.0": "They are the best girls around.",
    "room.408.chat.70.text": "You know, you're my first real girlfriend. I'm usually too busy to date, but ever since we met at Sausage I knew you were the one. That might be pretty forward, but no one has ever caused this much... excitement in my life. When I see you I just think dating, marriage, and 3 little kids running around.",
    "room.408.chat.70.choice.0": "...well I",
    "room.408.chat.71.text": "You don't have to say anything. I know it's way too soon to go out and buy houses yet. I just want you to know you're not just some fling with me. You're my everything and I want to see how this goes.",
    "room.408.chat.71.choice.0": "You're really sweet.",
    "room.408.chat.72.text": "[You two continue to make small talk for a while about your lives and desires.]",
    "room.408.chat.72.choice.0": "[Head back to the trailer]",
    "room.408.chat.73.text": "I had a great time today and I so much want to see you again. You can come by tomorrow, or really any day. I love you. *mwah*",
    "room.408.chat.73.choice.0": "*mwah* I love you too",
    "room.408.chat.73.choice.1": "*mwah*",
    "room.408.chat.74.text": "Looking for my step bro, {elijah}? He found a place at the homeless camp. Last tent in the middle. It is really nice. You should go see him. I haven't seen him this happy since our dad died.",
    "room.408.chat.74.choice.0": "oh thanks. I'll check it out.",
